mapper.select:
SELECT COUNT(1)
  FROM SY_AFFIRM_LEVEL_SETUP
 WHERE CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND DUTY = #{duty, jdbcType=VARCHAR}

mapper.update:
UPDATE SY_AFFIRM_LEVEL_SETUP
   SET AFFIRM_LEVEL = #{affirmLevel, jdbcType=INTEGER},
       UPDATE_DATE  = SYSDATE,
       UPDATED_BY   = #{adminID, jdbcType=VARCHAR}
 WHERE CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND DUTY = #{duty, jdbcType=VARCHAR}

mapper.delete:
DELETE FROM SY_AFFIRM_LEVEL_SETUP
 WHERE CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND DUTY = #{duty, jdbcType=VARCHAR}
